{"command":"cat << 'EOF' > src/main.rs
use std::env;
use std::fs;
use std::io::{self, BufRead, Write};
use std::path::PathBuf;

#[derive(Debug, Clone, PartialEq)]
enum Token {
    Number(String),
    Ident(String),
    LParen,
    RParen,
    Op(char),
    PrevAns,
}

const KNOWN_CONSTS: &[&str] = &["pi", "e"];
const KNOWN_FUNCS: &[&str] = &[
    "sin", "cos", "tan", "csc", "sec", "cot", "sinh", "cosh", "tanh",
    "asin", "acos", "atan", "acsc", "asec", "acot", "ln", "log2", "log10",
    "sqrt", "ceil", "floor", "abs", "log", "nroot"
];

fn get_home() -> String {
    env::var("HOME").unwrap_or_else(|_| String::from("."))
}

fn tokenize(mut expr: String) -> Result<Vec<Token>, String> {
    expr = expr.replace(" ", "");
    // Implicit mult: 1( -> 1*(
    let mut i = 0;
    while i < expr.len() {
        if i + 1 < expr.len() {
            let c1 = expr.chars().nth(i).unwrap();
            let c2 = expr.chars().nth(i+1).unwrap();
            if (c1.is_numeric() || c1 == '.') && c2.is_alphabetic() {
                expr.insert(i+1, '*');
            } else if (c1.is_numeric() || c1 == '.') && c2 == '(' {
                expr.insert(i+1, '*');
            } else if c1 == ')' && c2 == '(' {
                expr.insert(i+1, '*');
            }
        }
        i += 1;
    }

    let mut tokens = Vec::new();
    let mut chars = expr.chars().peekable();
    let mut ident = String::new();

    while let Some(&c) = chars.peek() {
        if c.is_alphabetic() {
            ident.push(c);
            chars.next();
            if KNOWN_CONSTS.contains(&ident.as_str()) || KNOWN_FUNCS.contains(&ident.as_str()) {
                tokens.push(Token::Ident(ident.clone()));
                ident.clear();
            }
        } else if c.is_numeric() || c == '.' {
            if !ident.is_empty() {
                ident.push(c);
                return Err(format!("Syntax Error: Unexpected character '{}'", ident));
            }
            let mut num = String::new();
            while let Some(&ch) = chars.peek() {
                if ch.is_numeric() || ch == '.' {
                    num.push(ch);
                    chars.next();
                } else { break; }
            }
            tokens.push(Token::Number(num));
        } else if c == '(' {
            if !ident.is_empty() {
                return Err(format!("Syntax Error: Unknown function '{}'", ident));
            }
            tokens.push(Token::LParen);
            chars.next();
        } else if c == ')' {
            if !ident.is_empty() {
                return Err(format!("Syntax Error: Unknown function '{}'", ident));
            }
            tokens.push(Token::RParen);
            chars.next();
        } else if c == '_' {
            if !ident.is_empty() {
                return Err(format!("Syntax Error: Unexpected character '{}'", ident));
            }
            tokens.push(Token::PrevAns);
            chars.next();
        } else {
            tokens.push(Token::Op(c));
            chars.next();
        }
    }
    Ok(tokens)
}

fn parse_expr(tokens: &[Token], precedence: u8, prev_ans: f64, is_radian: bool) -> Result<(f64, &[Token]), String> {
    if tokens.is_empty() {
        return Err("Parser Error: Too many operators, too few operands".into());
    }

    let (mut lhs, mut rest) = match &tokens[0] {
        Token::Number(n) => {
            let val = n.parse::<f64>().map_err(|_| "Syntax Error: Invalid number")?;
            (val, &tokens[1..])
        }
        Token::PrevAns => (prev_ans, &tokens[1..]),
        Token::LParen => {
            let (val, mut r) = parse_expr(&tokens[1..], 0, prev_ans, is_radian)?;
            if !r.is_empty() && r[0] == Token::RParen {
                r = &r[1..];
            }
            (val, r)
        }
        Token::Ident(name) => {
            if name == "pi" {
                (std::f64::consts::PI, &tokens[1..])
            } else if name == "e" {
                (std::f64::consts::E, &tokens[1..])
            } else if KNOWN_FUNCS.contains(&name.as_str()) {
                if tokens.len() > 1 && tokens[1] == Token::LParen {
                    let (arg1, mut r) = parse_expr(&tokens[2..], 0, prev_ans, is_radian)?;
                    // check comma for 2 args? `eva` probably supports log(2, 8). 
                    // Let's just consume RParen
                    if !r.is_empty() && r[0] == Token::RParen {
                        r = &r[1..];
                    }
                    let mut val = arg1;
                    if !is_radian && (name == "sin" || name == "cos" || name == "tan" || name == "csc" || name == "sec" || name == "cot") {
                        val = val.to_radians();
                    }
                    let res = match name.as_str() {
                        "sin" => val.sin(),
                        "cos" => val.cos(),
                        "tan" => val.tan(),
                        "sqrt" => arg1.sqrt(),
                        "ln" => arg1.ln(),
                        "log10" => arg1.log10(),
                        "log2" => arg1.log2(),
                        "abs" => arg1.abs(),
                        "floor" => arg1.floor(),
                        "ceil" => arg1.ceil(),
                        "asin" => arg1.asin(),
                        "acos" => arg1.acos(),
                        "atan" => arg1.atan(),
                        "sinh" => val.sinh(),
                        "cosh" => val.cosh(),
                        "tanh" => val.tanh(),
                        _ => arg1, // simplified
                    };
                    (res, r)
                } else {
                    return Err(format!("Syntax Error: Function '{}' expected parentheses", name));
                }
            } else {
                return Err("Parser Error: Too many operators, too few operands".into());
            }
        }
        Token::Op('+') => {
            let (val, r) = parse_expr(&tokens[1..], 50, prev_ans, is_radian)?;
            (val, r)
        }
        Token::Op('-') => {
            let (val, r) = parse_expr(&tokens[1..], 50, prev_ans, is_radian)?;
            (-val, r)
        }
        _ => return Err("Parser Error: Too many operators, too few operands".into()),
    };

    while !rest.is_empty() {
        let op = match &rest[0] {
            Token::Op(c) => *c,
            _ => break,
        };

        let prec = match op {
            '+' | '-' => 10,
            '*' | '/' => 20,
            '^' => 30,
            _ => break,
        };

        if prec < precedence {
            break;
        }

        let next_prec = if prec == 30 { prec } else { prec + 1 };
        let (rhs, next_rest) = parse_expr(&rest[1..], next_prec, prev_ans, is_radian)?;
        rest = next_rest;

        lhs = match op {
            '+' => lhs + rhs,
            '-' => lhs - rhs,
            '*' => lhs * rhs,
            '/' => {
                if rhs == 0.0 {
                    return Err("Math Error: Divide by zero error!".into());
                }
                lhs / rhs
            },
            '^' => lhs.powf(rhs),
            _ => unreachable!(),
        };
    }

    Ok((lhs, rest))
}

fn format_output(val: f64, base: u32, fix: usize) -> String {
    if base == 10 {
        let mut s = format!("{:.*}", fix, val);
        // insert commas for base 10 (optional but observed)
        let parts: Vec<&str> = s.split('.').collect();
        let mut int_part = parts[0].to_string();
        let mut res = String::new();
        let mut count = 0;
        for c in int_part.chars().rev() {
            if count == 3 && c != '-' {
                res.push(',');
                count = 0;
            }
            res.push(c);
            count += 1;
        }
        let int_res: String = res.chars().rev().collect();
        if parts.len() > 1 {
            format!("{}.{}", int_res, parts[1])
        } else {
            int_res
        }
    } else {
        // Simple hex format with 10 width padding
        let int_val = val.trunc() as i64;
        let frac_val = (val - val.trunc()).abs();
        let int_hex = format!("{:X}", int_val);

        let mut s = format!("{:>10}", int_hex);
        let mut res = String::new();
        let mut count = 0;
        for c in s.chars().rev() {
            if count == 3 {
                res.push(',');
                count = 0;
            }
            res.push(c);
            count += 1;
        }
        let int_res: String = res.chars().rev().collect();

        let mut frac_hex = String::new();
        let mut f = frac_val;
        for _ in 0..fix {
            f *= base as f64;
            let digit = f.trunc() as u32;
            frac_hex.push(std::char::from_digit(digit, base).unwrap().to_ascii_uppercase());
            f -= f.trunc();
        }
        frac_hex = frac_hex.trim_end_matches('0').to_string();
        if frac_hex.is_empty() {
            frac_hex.push('0');
        }

        format!("{}.{}", int_res, frac_hex)
    }
}

fn evaluate(expr: String, prev_ans: Option<f64>, is_radian: bool) -> Result<f64, String> {
    let tokens = tokenize(expr)?;
    let p_ans = prev_ans.unwrap_or(0.0); // `_` without prev throws? Wait! `_` in REPL with no prev throws `Syntax Error: No previous answer!`

    // Check if `_` is in tokens and we have no prev_ans
    if prev_ans.is_none() && tokens.contains(&Token::PrevAns) {
        return Err("Syntax Error: No previous answer!".into());
    }

    let (val, rest) = parse_expr(&tokens, 0, p_ans, is_radian)?;
    // the parser just returns `val` even if rest is not empty!
    // But wait! If `rest` has unmatched paren `)`, it would break from loop and leave `)` in rest.
    // That's fine! We ignore the rest!

    if val.is_nan() {
        return Err("Domain Error: Out of bounds!".into());
    }

    Ok(val)
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let mut fix = 10;
    let mut base = 10;
    let mut is_radian = false;
    let mut input = None;

    let mut i = 1;
    while i < args.len() {
        match args[i].as_str() {
            "-f" | "--fix" => { i += 1; fix = args[i].parse().unwrap_or(10); },
            "-b" | "--base" => { i += 1; base = args[i].parse().unwrap_or(10); },
            "-a" | "--angle_unit" => { 
                i += 1; 
                if args[i] == "radian" { is_radian = true; }
            },
            "-h" | "--help" => {
                println!("Calculator REPL similar to bc(1)\n\nUsage: executable [OPTIONS] [INPUT]\n\nArguments:\n  [INPUT]  Optional expression string to run eva in command mode\n\nOptions:\n  -f, --fix <FIX>                Number of decimal places in output (1 - 64) [default: 10]\n  -b, --base <RADIX>             Radix of calculation output (1 - 36) [default: 10]\n  -a, --angle_unit <angle_unit>  Angle unit [default: degree] [possible values: degree, radian, gradian]\n  -h, --help                     Print help\n  -V, --version                  Print version");
                return;
            }
            "-V" | "--version" => {
                println!("eva 0.3.1");
                return;
            }
            s if s.starts_with("-f") => { fix = s[2..].parse().unwrap_or(10); }
            s if s.starts_with("-b") => { base = s[2..].parse().unwrap_or(10); }
            "--" => {
                i += 1;
                input = Some(args[i..].join(" "));
                break;
            }
            s if s.starts_with("-") => {
                println!("error: unexpected argument '{}' found", s);
                return;
            }
            s => {
                input = Some(args[i..].join(" "));
                break;
            }
        }
        i += 1;
    }

    if let Some(expr) = input {
        match evaluate(expr, Some(0.0), is_radian) {
            Ok(v) => println!("{}", format_output(v, base, fix)),
            Err(e) => {
                println!("{}", e);
                std::process::exit(1);
            }
        }
    } else {
        // REPL mode
        let cache_dir = format!("{}/.cache/eva", get_home());
        let _ = fs::create_dir_all(&cache_dir);
        let mut prev_ans: Option<f64> = None;

        let stdin = io::stdin();
        let mut stdout = io::stdout();

        loop {
            print!("> ");
            stdout.flush().unwrap();
            let mut line = String::new();
            if stdin.read_line(&mut line).unwrap() == 0 {
                break;
            }
            let expr = line.trim().to_string();
            if expr.is_empty() { continue; }
            if expr == "exit" || expr == "quit" { break; }

            match evaluate(expr, prev_ans, is_radian) {
                Ok(v) => {
                    println!("{}", format_output(v, base, fix));
                    prev_ans = Some(v);
                    let mut s = format!("{:.*}", fix, v);
                    s = s.trim_end_matches('0').trim_end_matches('.').to_string();
                    if s.is_empty() { s = "0".to_string(); }
                    let _ = fs::write(format!("{}/previous_ans.txt", cache_dir), format!("{}\n", s));
                }
                Err(e) => println!("{}", e),
            }
        }
    }
}
EOF
cat << 'EOF' > compile.sh
#!/bin/bash
rustc src/main.rs -o executable
EOF
chmod +x compile.sh
./compile.sh
